80	    return schemaHandler;
81	  }
82	
83	  public void setSchemaHandler(FileGroupReaderSchemaHandler<T> schemaHandler) {
84	    this.schemaHandler = schemaHandler;
85	  }
86	
87	  public String getTablePath() {
88	    if (tablePath == null) {
89	      throw new IllegalStateException("Table path not set in reader context.");
90	    }
91	    return tablePath;
92	  }
93	
94	  public void setTablePath(String tablePath) {
95	    this.tablePath = tablePath;
96	  }
97	
98	  public String getLatestCommitTime() {
99	    return latestCommitTime;
100	  }
101	
102	  public void setLatestCommitTime(String latestCommitTime) {
103	    this.latestCommitTime = latestCommitTime;
104	  }
105	
106	  public Option<HoodieRecordMerger> getRecordMerger() {
107	    return recordMerger;
108	  }
109	
110	  public void setRecordMerger(Option<HoodieRecordMerger> recordMerger) {
111	    this.recordMerger = recordMerger;
112	  }
113	
