57	  // Set the instantTime for each record set.
58	  protected static List<String> instantTimes;
59	  protected static List<Boolean> shouldWritePositions;
60	
61	  // Environmental variables.
62	  protected static StorageConfiguration<?> storageConf;
63	  protected static HoodieTestTable testTable;
64	  protected static HoodieReaderContext<IndexedRecord> readerContext;
65	  protected static TypedProperties properties;
66	
67	  static {
68	    // Note: Make `timestamp` as ordering field.
69	    properties = new TypedProperties();
70	    properties.setProperty(
71	        "hoodie.datasource.write.precombine.field", "timestamp");
72	    storageConf = getDefaultStorageConf();
73	    readerContext = new HoodieTestReaderContext(
74	        Option.empty(), Option.empty());
75	  }
