143	            "1000", // Not used internally.
144	            AVRO_SCHEMA,
145	            shouldReadPositions,
146	            0L,
147	            Long.MAX_VALUE,
148	            properties,
149	            hoodieStorage,
150	            readerContext,
151	            metaClient,
152	            allowInflightCommits);
153	
154	    fileGroupReader.initRecordIterators();
155	    return fileGroupReader.getClosableIterator();
156	  }
